module robot_checker (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] instruction,\n    input wire [3:0] target_x,\n    input wire [3:0] target_y,\n    output reg result,\n    output reg done\n);\n\n    // State definitions\n    localparam [1:0] IDLE  = 2'd0;\n    localparam [1:0] PARSE = 2'd1;\n    localparam [1:0] CHECK = 2'd2;\n    localparam [1:0] DONE  = 2'd3;\n    \n    reg [1:0] state;\n    reg [7:0] cycle_count;\n    localparam [7:0] MAX_CYCLES = 8'd100;\n    \n    // Segment storage\n    reg [3:0] segments [0:4];\n\n    // Parse variables\n    integer i;\n    reg [3:0] count;\n    reg [2:0] seg_idx;\n\n    // Movement components\n    wire signed [4:0] x0_s, x2_s, x4_s, y1_s, y3_s;\n    wire signed [4:0] x_target_s, y_target_s, x_target_adj;\n    wire signed [4:0] x_cand [0:8];\n    wire signed [4:0] y_cand [0:8];\n    wire x_check, y_check;\n\n    // Parsing combinational logic\n    always @(*) begin\n        // Initialize\n        count = 4'd0;\n        seg_idx = 3'd0;\n        for (i = 0; i < 5; i = i + 1) begin\n            segments[i] = 4'd0;\n        end\n        \n        // Process instruction bits\n        for (i = 0; i < 8; i = i + 1) begin\n            if (instruction[i]) begin\n                count = count + 4'd1;\n                if (i == 7 && seg_idx < 5) begin\n                    segments[seg_idx] = count;\n                end\n            end else begin\n                if (seg_idx < 5) begin\n                    segments[seg_idx] = count;\n                    seg_idx = seg_idx + 3'd1;\n                end\n                count = 4'd0;\n            end\n        end\n    end\n\n    // Sign extend segments and targets\n    assign x0_s = $signed({1'b0, segments[0]});\n    assign x2_s = $signed({1'b0, segments[2]});\n    assign x4_s = $signed({1'b0, segments[4]});\n    assign y1_s = $signed({1'b0, segments[1]});\n    assign y3_s = $signed({1'b0, segments[3]});\n    assign x_target_s = { {1{target_x[3]}}, target_x };\n    assign y_target_s = { {1{target_y[3]}}, target_y };\n    assign x_target_adj = x_target_s - x0_s;\n\n    // X candidate combinations (9 options)\n    assign x_cand[0] = 5'sd0;\n    assign x_cand[1] = x2_s;\n    assign x_cand[2] = -x2_s;\n    assign x_cand[3] = x4_s;\n    assign x_cand[4] = -x4_s;\n    assign x_cand[5] = x2_s + x4_s;\n    assign x_cand[6] = x2_s - x4_s;\n    assign x_cand[7] = -x2_s + x4_s;\n    assign x_cand[8] = -x2_s - x4_s;\n\n    // Y candidate combinations (9 options)\n    assign y_cand[0] = 5'sd0;\n    assign y_cand[1] = y1_s;\n    assign y_cand[2] = -y1_s;\n    assign y_cand[3] = y3_s;\n    assign y_cand[4] = -y3_s;\n    assign y_cand[5] = y1_s + y3_s;\n    assign y_cand[6] = y1_s - y3_s;\n    assign y_cand[7] = -y1_s + y3_s;\n    assign y_cand[8] = -y1_s - y3_s;\n\n    // Check if targets match any candidate\n    assign x_check = (x_target_adj == x_cand[0]) || (x_target_adj == x_cand[1]) ||\n                     (x_target_adj == x_cand[2]) || (x_target_adj == x_cand[3]) ||\n                     (x_target_adj == x_cand[4]) || (x_target_adj == x_cand[5]) ||\n                     (x_target_adj == x_cand[6]) || (x_target_adj == x_cand[7]) ||\n                     (x_target_adj == x_cand[8]);\n                     \n    assign y_check = (y_target_s == y_cand[0]) || (y_target_s == y_cand[1]) ||\n                     (y_target_s == y_cand[2]) || (y_target_s == y_cand[3]) ||\n                     (y_target_s == y_cand[4]) || (y_target_s == y_cand[5]) ||\n                     (y_target_s == y_cand[6]) || (y_target_s == y_cand[7]) ||\n                     (y_target_s == y_cand[8]);\n\n    // State machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 1'b0;\n            done <= 1'b0;\n            cycle_count <= 8'd0;\n            // Initialize array elements\n            for (i = 0; i < 5; i = i + 1) begin\n                segments[i] <= 4'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    cycle_count <= 8'd0;\n                    if (start) begin\n                        state <= PARSE;\n                    end\n                end\n                \n                PARSE: begin\n                    cycle_count <= cycle_count + 8'd1;\n                    state <= CHECK;\n                end\n                \n                CHECK: begin\n                    cycle_count <= cycle_count + 8'd1;\n                    result <= x_check && y_check;\n                    state <= DONE;\n                end\n                \n                DONE: begin\n                    done <= 1'b1;\n                    if (!start) begin\n                        state <= IDLE;\n                    end\n                    // Cycle count timeout\n                    if (cycle_count >= MAX_CYCLES) begin\n                        state <= IDLE;\n                    end\n                end\n                \n                default: begin\n                    state <= IDLE;\n                end\n            endcase\n        end\n    end\nendmodule